function microAdventuresPage(){const ideas=active(store.state).filter(r=>['experiencePlan','experience'].includes(r.type)&&r.status!=='Done');return heading('A LITTLE DELIGHT, WITHIN MY REAL LIFE','Micro-Adventures Generator','Pick from places and ideas you saved yourself, within the budget, time, setting and energy you choose.','experiencePlan')+`<section class="panel"><h2>Save my own adventure ideas</h2><p>Only your saved ideas can be suggested. No events, prices or opening hours are invented.</p><button class="softbutton" data-action="new" data-type="experiencePlan">Add an adventure idea ♡</button><form id="adventure-form" class="formgrid"><label>Maximum budget (USD)<input name="budget" inputmode="decimal" value="0" required></label><label>Time available (minutes)<input name="minutes" type="number" min="5" max="1440" value="90"></label><label>Energy<select name="energy"><option>Low</option><option selected>Medium</option><option>High</option></select></label><label>Setting<select name="setting"><option>Any</option><option>Indoor</option><option>Outdoor</option></select></label><button class="heart-pill">Surprise me from my saved ideas ♡</button></form><div id="adventure-result" role="status">${adventureChoice?`<article class="recordcard"><h3>${esc(adventureChoice.title)}</h3><p>${esc(adventureChoice.data.location||adventureChoice.data.place||'Location not entered')} · ${dollars(adventureChoice.data.amount||0)} estimate · ${Number(adventureChoice.data.duration)||30} minutes</p><button class="softbutton" data-action="edit" data-id="${esc(adventureChoice.id)}">Review my idea</button></article>`:'<p>Choose constraints, then draw one idea.</p>'}</div></section><section class="panel"><h2>My saved adventure ideas</h2><div class="recordgrid">${ideas.map(card).join('')||'<p>Add a few ideas before asking for a surprise.</p>'}</div></section>`;}
