$('#backup-input').addEventListener('change',async e=>{const input=e.currentTarget;try{const file=input.files[0];if(!file)return;if(file.size>30*1024*1024)throw Error('Choose a backup under 30 MB.');const json=JSON.parse(await file.text());let incoming,warnings=[],encryptedFull=json.format==='dreamhub-vault-backup';if(encryptedFull){const pass=prompt('Enter the passphrase for this encrypted DreamHub backup.');if(pass===null)return;incoming=await decryptMainBackup(json,pass);}else if(json.version===1){const migrated=migrateLegacy(json);incoming=migrated.state;warnings=migrated.warnings;}else incoming=validate(json.state||json);pendingImport=incoming;if(encryptedFull){const accepted=await confirmAction('Restore this full backup?',`${incoming.records.length} records will replace the current workspace, including its preferences, rules, budgets, and history. Export your current data first if you may need it. DreamHub cannot undo this replacement.`,null,'Replace with backup');if(accepted)await act(()=>store.restoreBackup(pendingImport),'Your encrypted backup has been restored. ♡');}else{const plan=previewImport(store.state,incoming),safeName=String(file.name||'Imported backup').replace(/[\u0000-\u001f]/g,'').slice(0,160),conflictList=plan.conflicts.slice(0,8).map(x=>`• ${x.incoming.sensitive?'[Private title hidden]':x.incoming.title} · ${types[x.incoming.type]?.name||x.incoming.type}`).join('\n'),more=plan.conflicts.length>8?`\n…and ${plan.conflicts.length-8} more conflicts.`:'';const detail=`File: ${safeName}\n${plan.added.length} new · ${plan.identical.length} already identical · ${plan.conflicts.length} conflicting IDs.\n${plan.conflicts.length?'Conflict review (current versions will be kept):\n'+conflictList+more:'No conflicting IDs.'}\nOnly new records will be added. Nothing will replace a current record. The import will be recorded in your history and each added record will retain its source. ${warnings.join(' ')}`;const accepted=await confirmAction('Review this import',detail,null,plan.conflicts.length?'Import new pages & keep current versions':'Import new pages');if(accepted)await act(()=>store.import(pendingImport,{conflictPolicy:'keep-existing',sourceLabel:safeName}),'Import reviewed and recorded. New pages were added; current conflicts were kept. ♡');}}catch(err){error('Import stopped: '+err.message)}finally{input.value='';pendingImport=null;}});
$('#editor').addEventListener('cancel',e=>{if(!saveDraft())e.preventDefault();});
window.addEventListener('hashchange',()=>{if($('#editor').open){if(!saveDraft()){location.hash=route;return;}$('#editor').close();}route=location.hash.slice(1)||'home';tab='all';filter='';writingQuery='';mobile=false;rememberPlace(route);render();window.scrollTo({top:0,behavior:'instant'});});
