let ticking=false;setInterval(async()=>{const t=store.state.timer;document.querySelectorAll('[data-clock]').forEach(e=>e.textContent=timerText());if(t?.running&&t.endAt<=Date.now()&&!ticking){ticking=true;try{await store.update(s=>{if(!s.timer?.running||s.timer.endAt>Date.now())return;const finished=s.timer,title=finished.kind==='break'?'A little rest break':s.records.find(r=>r.id===finished.taskId)?.title||'A little focus';s.sessions.push({id:uid(),at:now(),title,minutes:finished.duration,kind:finished.kind||'focus',taskId:finished.taskId||null});s.sessions=s.sessions.slice(-100);s.timer={...s.timer,running:false,remaining:0};});if(store.state.settings.focusSound)playLocalFocusTone();render();toast(store.state.timer?.kind==='break'?'Your little break is complete. Come back when you’re ready. ♡':'Your little focus session is complete. Time for a breath. ♡');}catch(e){error('Session completion could not be saved: '+e.message)}finally{ticking=false;}}},500);
